                    // Deflate: treat u as separate eigenvalue
                    u = u - 1;
                    if (u <= l) {
                        converged = true;
                        break;
                    }
                    continue;
                }
            }

            // Wilkinson shift: use eigenvalue of bottom 2x2 submatrix
            double shift = ZERO;
            if (u > l) {
                double a = d(u-1);
                double b = d(u);
                double c = o(u-1); // off-diagonal between u-1 and u
                double trace = a + b;
                double det = a * b - c;
